Compute the global variables to get initialized.

CodeV0 &lt;- getInitialPrice() # Checks google finance and gets price
vol &lt;- getVolatility() # Calculates volatility from google finance

Vmin &lt;- V0 - 4 * vol * V0
Vmax &lt;- V0 + 4 * vol * V0 - 0.01

V &lt;- 0
i &lt;- 0
while((Vmin + i) &lt;= Vmax) {
  V &lt;- Vmin + i
  Distribution[[round(V, 2)]] &lt;- pnorm(-4 * vol * V0 + i + 0.01, 0, vol * V0) - pnorm(-4 * vol * V0 + i, 0, vol * V0)

  i &lt;- i + 0.01
}

Pb &lt;- V0 - vol * V0 * 0.5
Pa &lt;- V0 + vol * V0 * 0.5

TruePrice &lt;- c(TruePrice, V0)


Now put to work. Every time it received an order, it will update price distribution and bid/ask prices. Market making is all about give price for trading.

Code# Update the probability densities
updateDensity = function(OrderSide) {
  if (OrderSide == "SELL") {
    for (price in names(Distribution)) {
      if (as.numeric(price) &lt;= Pb) {
        post &lt;- (1 - setAlpha) * 0.5 + setAlpha * pnorm(Pb - as.numeric(price), 0, setNoise * V0)
        Distribution[[price]] &lt;- post * Distribution[[price]] / 0.5
          } else {
        post &lt;- (1 - setAlpha) * 0.5 + setAlpha * (1 - pnorm(as.numeric(price) - Pb, 0, setNoise * V0))
        Distribution[[price]] &lt;- post * Distribution[[price]] / 0.5
          }
        }
      } else {
    for (price in names(Distribution)) {
          if (as.numeric(price) &lt;= Pa) {
        post &lt;- (1 - setAlpha) * 0.5 + setAlpha * (1 - pnorm(Pa - as.numeric(price), 0, setNoise * V0))
        Distribution[[price]] &lt;- post * Distribution[[price]] / 0.5
          }
        }
      }
    }
#updateDensity("SELL") 

# Update the bid-ask spread
updateSpread = function() {
  cumSum1 &lt;- 0
  cumSum2 &lt;- 0

  for (price in names(Distribution)) {
    if (as.numeric(price) &lt;= Pb) {
      a &lt;- Pb - as.numeric(price)
      cumSum1 &lt;- cumSum1 + (0.5 - 0.5 * setAlpha + setAlpha * pnorm(a, 0, setNoise * V0)) *
        Distribution[[price]] * as.numeric(price)
    } else {
      a &lt;- as.numeric(price) - Pb
      cumSum2 &lt;- cumSum2 + (0.5 - 0.5 * setAlpha + setAlpha * (1 - pnorm(a, 0, setNoise * V0))) *
        Distribution[[price]] * as.numeric(price)
    }
  }

  newPb &lt;- 2 * (cumSum1 + cumSum2)

  cumSum1 &lt;- 0
  cumSum2 &lt;- 0

  for (price in names(Distribution)) {
    if (as.numeric(price) &lt;= Pa) {
      a &lt;- Pa - as.numeric(price)
      cumSum1 &lt;- cumSum1 + (0.5 - 0.5 * setAlpha + setAlpha * (1 - pnorm(a, 0, setNoise * V0))) *
          Distribution[[price]] * as.numeric(price)
      } else {
        a &lt;- as.numeric(price) - Pa
        cumSum2 &lt;- cumSum2 + (0.5 - 0.5 * setAlpha + setAlpha * pnorm(a, 0, setNoise * V0)) *
          Distribution[[price]] * as.numeric(price)
      }
    }

  newPa &lt;- 2 * (cumSum1 + cumSum2)
  Pb &lt;- newPb
  Pa &lt;- newPa

  TruePrice &lt;- c(TruePrice, (Pa + Pb)/2) # Add the true price to our list
  return(list(Pa, Pb)) # Returns Pa and Pb so that we can input the new orders
}


